import{_ as p,a0 as r,w as o,s as d,ao as l,I as t,a1 as i,A as n,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"NoSQL： 如何在 Ubuntu 16.04 上安裝 OrientDB | LCTT x X-CMD","titleTemplate":false,"description":"NoSQL： 如何在 Ubuntu 16.04 上安裝 OrientDB | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"NoSQL： 如何在 Ubuntu 16.04 上安裝 OrientDB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"NoSQL： 如何在 Ubuntu 16.04 上安裝 OrientDB | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170712 NoSQL How To Install OrientDB on Ubuntu 16.04","title":"NoSQL： 如何在 Ubuntu 16.04 上安裝 OrientDB","tag":"201707","desc":""},"relativePath":"201707/20170712 NoSQL How To Install OrientDB on Ubuntu 16.04.md","filePath":"[post].md"}'),h={name:"201707/20170712 NoSQL How To Install OrientDB on Ubuntu 16.04.md"};function b(c,s,g,u,k,f){const a=r("Link");return o(),d("div",null,[s[17]||(s[17]=l('<h1 id="nosql-如何在-ubuntu-16-04-上安裝-orientdb" tabindex="-1">NoSQL： 如何在 Ubuntu 16.04 上安裝 OrientDB <a class="header-anchor" href="#nosql-如何在-ubuntu-16-04-上安裝-orientdb" aria-label="Permalink to “NoSQL： 如何在 Ubuntu 16.04 上安裝 OrientDB”">​</a></h1><p><img src="https://www.unixmen.com/wp-content/uploads/2017/07/orientdb-696x318.png" alt="OrientDB NoSQL DBMS" title="orientdb"></p><h3 id="説明-非關係型資料庫-nosql-和-orientdb" tabindex="-1">説明 - 非關係型資料庫（NoSQL）和 OrientDB <a class="header-anchor" href="#説明-非關係型資料庫-nosql-和-orientdb" aria-label="Permalink to “説明 - 非關係型資料庫（NoSQL）和 OrientDB”">​</a></h3><p>通常在我們提及資料庫的時候，想到的是兩個主要的分類：使用用於用户和應用程序之間進行對接的一種被稱為結構化查詢語言（<strong>S</strong>tructured <strong>Q</strong>uery <strong>L</strong>anguage ，縮寫 SQL）的關係型資料庫管理系統（<strong>R</strong>elational <strong>D</strong>ata <strong>b</strong>ase <strong>M</strong>anagement <strong>S</strong>ystem，縮寫 RDBMS） 以及非關係型資料庫管理系統（non-relational database management systems 或稱 NoSQL 資料庫）。</p><p>這兩種模型在如何處理（存儲）數據的方面存在着巨大的差異。</p><h4 id="關係資料庫管理系統" tabindex="-1">關係資料庫管理系統 <a class="header-anchor" href="#關係資料庫管理系統" aria-label="Permalink to “關係資料庫管理系統”">​</a></h4><p>在關係模型中（如 MySQL，或者其分支 MariaDB），一個數據庫是一個表的集合，其中每個表包含一個或多個以列組織的數據分類。資料庫的每行包含一個唯一的數據實例，其分類由列定義。</p><p>舉個例子，想像一個包含客户的表。每一行相當於一個客户，而其中的每一列分別對應名字、地址以及其他所必須的信息。</p><p>而另一個表可能是包含訂單、產品、客户、日期以及其它的種種。而這個資料庫的使用者則可以獲得一個滿足其需要的視圖，例如一個客户在一個特定的價格範圍購買產品的報告。</p><h4 id="非關係型資料庫管理系統" tabindex="-1">非關係型資料庫管理系統 <a class="header-anchor" href="#非關係型資料庫管理系統" aria-label="Permalink to “非關係型資料庫管理系統”">​</a></h4><p>在非關係型資料庫（或稱為<ruby>不僅僅是資料庫<rt>Not only SQL</rt></ruby>）管理系統中，資料庫被設計為使用不同的方式存儲數據，比如文檔存儲、鍵值對存儲、圖形關係存儲以及其他方式存儲。使用此種形式實現的資料庫系統專門被用於大型資料庫集羣和大型 Web 應用。現今，非關係型資料庫被用於某些大公司，如谷歌和亞馬遜。</p><h5 id="文檔存儲資料庫" tabindex="-1">文檔存儲資料庫 <a class="header-anchor" href="#文檔存儲資料庫" aria-label="Permalink to “文檔存儲資料庫”">​</a></h5><p>文檔存儲資料庫是將數據用文檔的形式存儲。這種類型的運用通常表現為 JavaScript 和 JSON，實際上，XML 和其他形式的存儲也是可以被採用的。這裏的一個例子就是 MongoDB。</p><h5 id="鍵值對存儲資料庫" tabindex="-1">鍵值對存儲資料庫 <a class="header-anchor" href="#鍵值對存儲資料庫" aria-label="Permalink to “鍵值對存儲資料庫”">​</a></h5><p>這是一個由唯一的<ruby>鍵<rt>key</rt></ruby>配對一個<ruby>值<rt>value</rt></ruby>的簡單模型。這個系統在高速緩存方面具有高性能和高度可擴展性。這裏的例子包括 BerkeleyDB 和 MemacacheDB。</p><h5 id="圖形關係資料庫" tabindex="-1">圖形關係資料庫 <a class="header-anchor" href="#圖形關係資料庫" aria-label="Permalink to “圖形關係資料庫”">​</a></h5><p>正如其名，這種資料庫通過使用<ruby>圖<rt>graph</rt></ruby>模型存儲數據，這意味着數據通過節點和節點之間的互連進行組織。這是一個可以隨着時間的推移和使用而發展的靈活模型。這個系統應用於那些強調映射關係的地方。這裏的例子有 IBM Graphs、Neo4j 以及 <strong>OrientDB</strong>。</p><h3 id="orientdb" tabindex="-1">OrientDB <a class="header-anchor" href="#orientdb" aria-label="Permalink to “OrientDB”">​</a></h3>',18)),t("p",null,[i(a,{href:"https://orientdb.com/"},{default:n(()=>[...s[0]||(s[0]=[e("OrientDB",-1)])]),_:1}),s[1]||(s[1]=e(" 是一個多模式的非關係型資料庫管理系統。正如開發它的公司所説的“",-1)),s[2]||(s[2]=t("em",null,[e("它是一個將圖形關係與文檔、鍵值對、反應性、面向對象和地理空間模型結合在一起的"),t("strong",null,"可擴展的、高性能的資料庫")],-1)),s[3]||(s[3]=e("”。",-1))]),s[18]||(s[18]=l(`<p>OrientDB 還支持 SQL ，經過擴展可以用來操作樹和圖。</p><h3 id="目標" tabindex="-1">目標 <a class="header-anchor" href="#目標" aria-label="Permalink to “目標”">​</a></h3><p>這個教程旨在教會大家如何在運行 Ubuntu 16.04 的服務器上下載並配置 OrientDB 社區版。</p><h3 id="下載-orientdb" tabindex="-1">下載 OrientDB <a class="header-anchor" href="#下載-orientdb" aria-label="Permalink to “下載 OrientDB”">​</a></h3><p>我們可以從最新的服務端上通過輸入下面的指令來下載最新版本的 OrientDB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget -O orientdb-community-2.2.22.tar.gz http://orientdb.com/download.php?file=orientdb-community-2.2.22.tar.gz&amp;os=linux</span></span></code></pre></div><p>這裏下載的是一個包含預編譯二進制文件的壓縮包，所以我們可以使用 <code>tar</code> 指令來操作解壓它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -zxf orientdb-community-2.2.22.tar.gz</span></span></code></pre></div><p>將從中提取出來的文件夾整體移動到 <code>/opt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mv orientdb-community-2.2.22 /opt/orientdb</span></span></code></pre></div><h3 id="啓動-orientdb-服務器" tabindex="-1">啓動 OrientDB 服務器 <a class="header-anchor" href="#啓動-orientdb-服務器" aria-label="Permalink to “啓動 OrientDB 服務器”">​</a></h3><p>啓動 OrientDB 服務器需要運行 <code>orientdb/bin/</code> 目錄下的 shell 腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /opt/orientdb/bin/server.sh</span></span></code></pre></div><p>如果你是第一次開啓 OrientDB 服務器，安裝程序還會顯示一些提示信息，以及提醒你設置 OrientDB 的 root 用户密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+---------------------------------------------------------------+</span></span>
<span class="line"><span>| WARNING: FIRST RUN CONFIGURATION |</span></span>
<span class="line"><span>+---------------------------------------------------------------+</span></span>
<span class="line"><span>| This is the first time the server is running. Please type a |</span></span>
<span class="line"><span>| password of your choice for the &#39;root&#39; user or leave it blank |</span></span>
<span class="line"><span>| to auto-generate it. |</span></span>
<span class="line"><span>| |</span></span>
<span class="line"><span>| To avoid this message set the environment variable or JVM |</span></span>
<span class="line"><span>| setting ORIENTDB_ROOT_PASSWORD to the root password to use. |</span></span>
<span class="line"><span>+---------------------------------------------------------------+</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Root password [BLANK=auto generate it]: ********</span></span>
<span class="line"><span>Please confirm the root password: ********</span></span></code></pre></div><p>在完成這些後，OrientDB 資料庫服務器將成功啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>INFO OrientDB Server is active v2.2.22 (build fb2b7d321ea8a5a5b18a82237049804aace9e3de). [OServer]</span></span></code></pre></div><p>從現在開始，我們需要用第二個終端來與 OrientDB 服務器進行交互。</p><p>若要強制停止 OrientDB 執行 <code>Ctrl+C</code> 即可。</p><h3 id="配置守護進程" tabindex="-1">配置守護進程 <a class="header-anchor" href="#配置守護進程" aria-label="Permalink to “配置守護進程”">​</a></h3><p>此時，我們可以認為 OrientDB 僅僅是一串 shell 腳本，可以用編輯器打開 <code>/opt/orientdb/bin/orientdb.sh</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /opt/orientdb/bin/orientdb.sh</span></span></code></pre></div><p>在它的首段，我們可以看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span># OrientDB service script</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Copyright (c) OrientDB LTD (http://orientdb.com/)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># chkconfig: 2345 20 80</span></span>
<span class="line"><span># description: OrientDb init script</span></span>
<span class="line"><span># processname: orientdb.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span># You have to SET the OrientDB installation directory here</span></span>
<span class="line"><span>ORIENTDB_DIR=&quot;YOUR_ORIENTDB_INSTALLATION_PATH&quot;</span></span>
<span class="line"><span>ORIENTDB_USER=&quot;USER_YOU_WANT_ORIENTDB_RUN_WITH&quot;</span></span></code></pre></div><p>我們需要配置<code>ORIENTDB_DIR</code> 以及 <code>ORIENTDB_USER</code>.</p><p>然後創建一個用户，例如我們創建一個名為 <code>orientdb</code> 的用户，我們需要輸入下面的指令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd -r orientdb -s /sbin/nologin</span></span></code></pre></div><p><code>orientdb</code> 就是我們在 <code>ORIENTDB_USER</code> 處輸入的用户。</p><p>再更改 <code>/opt/orientdb</code> 目錄的所有權：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chown -R orientdb:orientdb /opt/orientdb</span></span></code></pre></div><p>改變服務器配置文件的權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chmod 640 /opt/orientdb/config/orientdb-server-config.xml</span></span></code></pre></div><h4 id="下載系統守護進程服務" tabindex="-1">下載系統守護進程服務 <a class="header-anchor" href="#下載系統守護進程服務" aria-label="Permalink to “下載系統守護進程服務”">​</a></h4><p>OrientDB 的壓縮包包含一個服務文件 <code>/opt/orientdb/bin/orientdb.service</code>。我們將其複製到 <code>/etc/systemd/system</code> 文件夾下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp /opt/orientdb/bin/orientdb.service /etc/systemd/system</span></span></code></pre></div><p>編輯該服務文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># $EDITOR /etc/systemd/system/orientdb.service</span></span></code></pre></div><p>其中 <code>[service]</code> 內容塊看起來應該是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Service]</span></span>
<span class="line"><span>User=ORIENTDB_USER</span></span>
<span class="line"><span>Group=ORIENTDB_GROUP</span></span>
<span class="line"><span>ExecStart=$ORIENTDB_HOME/bin/server.sh</span></span></code></pre></div><p>將其改成如下樣式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Service]</span></span>
<span class="line"><span>User=orientdb </span></span>
<span class="line"><span>Group=orientdb </span></span>
<span class="line"><span>ExecStart=/opt/orientdb/bin/server.sh</span></span></code></pre></div><p>保存並退出。</p><p>重新加載系統守護進程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl daemon-reload</span></span></code></pre></div><p>啓動 OrientDB 並使其開機自啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl start orientdb</span></span>
<span class="line"><span># systemctl enable orientdb</span></span></code></pre></div><p>確認 OrientDB 的狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl status orientdb</span></span></code></pre></div><p>上述指令應該會輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>● orientdb.service - OrientDB Server</span></span>
<span class="line"><span> Loaded: loaded (/etc/systemd/system/orientdb.service; disabled; vendor preset: enabled)</span></span>
<span class="line"><span> Active: active (running) ...</span></span></code></pre></div><p>流程就是這樣了！OrientDB 社區版成功安裝並且正確運行在我們的服務器上了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這個指導中，我們看到了一些關係型資料庫管理系統（RDBMS）以及非關係型資料庫管理系統（NoSQL DBMS）的簡單對照。我們也安裝 OrientDB 社區版的服務器端並完成了其基礎的配置。</p><p>這是我們部署完全的 OrientDB 基礎設施的第一步，也是我們用於管理大型系統數據的起步。</p><hr>`,55)),t("p",null,[s[5]||(s[5]=e("via: ",-1)),i(a,{href:"https://www.unixmen.com/nosql-install-orientdb-ubuntu-16-04/"},{default:n(()=>[...s[4]||(s[4]=[e("https://www.unixmen.com/nosql-install-orientdb-ubuntu-16-04/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),i(a,{href:"https://www.unixmen.com/author/tutan/"},{default:n(()=>[...s[6]||(s[6]=[e("Giuseppe Molica",-1)])]),_:1}),s[10]||(s[10]=e(" 譯者：",-1)),i(a,{href:"https://github.com/a972667237"},{default:n(()=>[...s[7]||(s[7]=[e("a92667237",-1)])]),_:1}),s[11]||(s[11]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[12]||(s[12]=[e("LCTT",-1)])]),_:1}),s[15]||(s[15]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[13]||(s[13]=[e("Linux中國",-1)])]),_:1}),s[16]||(s[16]=e(" 榮譽推出",-1))])])}const v=p(h,[["render",b]]);export{D as __pageData,v as default};
